def scan(dirs):
    mains, forks, unreadable = [], 0, 0
    for d in dirs:
        try:
            names = os.listdir(d)
        except OSError:
            continue
        for n in names:
            if not n.endswith(".jsonl"):
                continue
            p = os.path.join(d, n)
            if not os.path.isfile(p):
                continue
            c = classify(p)
            if c == "main":
                mains.append((os.path.getmtime(p), n[:-6], p))
            elif c == "fork" or c == "lane":
                forks += 1
            else:
                unreadable += 1
    mains.sort(reverse=True)
    return mains, forks, unreadable


