def partition(pending_lines, live):
    """Return (quiescent_sessions, live_sessions, quiescent_subagents, live_subagents)."""
    q_s = l_s = q_b = l_b = 0
    for line in pending_lines:
        m = SUB.match(line)
        if m:
            key = m.group(1) + "/" + m.group(2)
            if key in live:
                l_b += 1
            else:
                q_b += 1
            continue
        m = TOP.match(line)
        if m:
            if m.group(1) in live:
                l_s += 1
            else:
                q_s += 1
    return q_s, l_s, q_b, l_b

