 def acquire(self):
     for _ in range(2):
         try:
             fd = os.open(str(self.path), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
             os.write(fd, str(time.time()).encode())
             os.close(fd)
             self.held = True
             return True
         except FileExistsError:
             try:
                 age = time.time() - self.path.stat().st_mtime
             except OSError:
                 age = 0
             if age > LOCK_STALE_S:
                 try:
                     self.path.unlink()
                     continue
                 except OSError:
                     return False
             return False
         except OSError:
             return False
     return False

 def release(self):
     if self.held:
         try:
             self.path.unlink()
         except OSError:
             pass
         self.held = False

