def parse_frontmatter(text):
    if not text.startswith("---"):
        return {}
    lines = text.split("\n")
    if lines[0].strip() != "---":
        return {}
    fm = {}
    for ln in lines[1:60]:
        if ln.strip() == "---":
            break
        m = re.match(r"^([A-Za-z0-9_\-]+):\s*(.*)$", ln)
        if m:
            fm[m.group(1).strip().lower()] = m.group(2).strip()
    return fm

