def corpus_files(root, globs):
    out = []
    for pat in globs:
        out.extend(glob.glob(os.path.join(root, pat), recursive=True))
    # de-dupe, stable order
    seen = set()
    result = []
    for p in out:
        norm = os.path.normpath(p)
        if norm not in seen and os.path.isfile(p):
            seen.add(norm)
            result.append(p)
    return sorted(result)


