def ngrams(text):
    """Character n-grams, deduplicated with counts. Operates on NORMALIZED text."""
    counts = {}
    n_text = len(text)
    for n in NGRAM_SIZES:
        if n_text < n:
            continue
        for i in range(n_text - n + 1):
            g = text[i:i + n]
