            cur = ln.strip()
        elif cur is not None and ln.strip() and not re.match(r"^#{1,6}\s", ln):
            cur += " " + ln.strip()
        elif cur is not None:
            out.append(cur)
            cur = None
    if cur is not None:
        out.append(cur)
    return out


