        if cells[0] in ("at", "---") or set(cells[0]) <= {"-"}:
            continue
        verb = cells[2] if len(cells) > 2 else ""
        work_item = cells[3] if len(cells) > 3 else ""
        if verb not in ("TAKE", "DONE", "RELEASE", "NOTE"):
            continue
        rows.append((verb, work_item))
    return rows

