                chunk += fh.read(64)   # overlap so a timestamp split across reads still matches
                for m in WATERMARK_TS_RE.finditer(chunk):
                    if m.group(1) > mx:
                        mx = m.group(1)
    except OSError:
        return None
    return mx.decode("ascii") if mx else None

