def section(text, num):
    """Body of `## {num}. ...` up to the next `## `. Empty string when absent."""
    m = re.search(rf"^##\s+{num}\.\s.*?$(.*?)(?=^##\s|\Z)", text, re.MULTILINE | re.DOTALL)
    return m.group(1) if m else ""


