                        continue
                    # human-authored only: type user, and either isMeta (mid-turn to a subagent)
                    # or origin.kind == human (a typed dispatch).
                    if d2.get("type") != "user":
                        continue
                    origin = (d2.get("origin") or {}).get("kind", "")
