def check_spec_liveness(root: Path, spec_path: Path):
    if not spec_path.is_file():
        return "UNKNOWN", f"no spec at {spec_path}", []
    present = {str(p.relative_to(root)).replace(os.sep, "/") for p in root.rglob("*") if p.is_file()}
    dead = []
    for ln in spec_path.read_text(encoding="utf-8", errors="replace").split(chr(10)):
        ln = ln.strip()
        if not ln or ln.startswith("#"):
            continue
        bits = ln.split()
        key, rest = bits[0], bits[1:]
        hit = False
        if key == "EXACT_INCLUDE" and rest:
            hit = rest[0] in present
        elif key == "PREFIX_INCLUDE" and rest:
            hit = any(p.startswith(rest[0]) for p in present)
        elif key == "SUFFIX_UNDER" and len(rest) == 2:
            hit = any(p.startswith(rest[0]) and p.endswith(rest[1]) for p in present)
        elif key == "BASENAME_UNDER" and len(rest) == 3:
            hit = any(p.startswith(rest[0]) and Path(p).name == rest[2] for p in present)
        else:
            continue
        if not hit:
            # A row dies for two very different reasons and lumping them hides the useful one: the
            # target may not exist at source (a stale rule), or it may exist and be WITHHELD by the
            # exclusion list -- a spec contradicting its own fence. [2026-09-13: the first real
            # finding was the second kind: INGEST-LEDGER.md asked for by an include and cut by
            # CONTENT-CARD on four Luhn-valid numbers.]
            why = "no file matched"
            log = root / "DERIVATION-LOG.md"
            if log.is_file() and rest:
                if rest[0] in log.read_text(encoding="utf-8", errors="replace"):
                    why = "CONTRADICTED: the target is WITHHELD by the exclusion list"
            dead.append(ln + "   [" + why + "]")
    verdict = "CLEAN" if not dead else "FINDING"
    return verdict, (f"{len(dead):,} spec row(s) produced NO file; a row marked CONTRADICTED is a "
                     f"spec asking for what its own fence refuses"), dead

CACHE_NAMES = ("__pycache__",)
CACHE_SUFFIXES = (".pyc", ".pyo")


def tree_digest(root: Path):
    h = hashlib.sha256()
    n = 0
    for p in sorted(root.rglob("*")):
        if any(part in CACHE_NAMES for part in p.parts) or p.suffix in CACHE_SUFFIXES:
            continue
        if p.is_file():
            h.update(str(p.relative_to(root)).replace(os.sep, "/").encode())
            h.update(str(p.stat().st_size).encode())
            n += 1
    return h.hexdigest(), n

def manifest_check(root: Path):
    """(verdict, detail). Verify the tree against its own shipped manifest -- an external reference."""
    man = root / "MANIFEST.sha256"
    if not man.is_file():
        return "ABSENT", f"no MANIFEST.sha256 at {root}; falling back to a self-taken baseline, "
    listed = {}
    for ln in man.read_text(encoding="utf-8", errors="replace").split(chr(10)):
        parts = ln.strip().split(None, 2)
        if len(parts) == 3 and len(parts[0]) == 64 and parts[1].isdigit():
            listed[parts[2].replace(chr(92), "/")] = (parts[0].lower(), int(parts[1]))
        elif len(parts) == 2 and len(parts[0]) == 64:
            listed[parts[1].replace(chr(92), "/")] = (parts[0].lower(), None)
    if not listed:
        return "UNPARSED", f"{man} parsed to 0 rows -- never treat that as clean"
    bad, missing, extra = [], [], []
    on_disk = {}
    for f in root.rglob("*"):
        if f.is_file() and not (any(x in CACHE_NAMES for x in f.parts)
                                or f.suffix in CACHE_SUFFIXES):
            on_disk[str(f.relative_to(root)).replace(os.sep, "/")] = f
    for rel, (sha, size) in listed.items():
        f = on_disk.get(rel)
        if f is None:
            missing.append(rel)
            continue
        h = hashlib.sha256()
        with open(f, "rb") as fh:
            for chunk in iter(lambda: fh.read(1 << 20), b""):
                h.update(chunk)
        if h.hexdigest() != sha or (size is not None and size != f.stat().st_size):
            bad.append(rel)
    # A manifest cannot list itself, and the derivation log is written after it. Counting those as
    # "unlisted" makes every CLEAN tree report DIVERGED -- red by construction, which is the defect I
    # repaired in the staleness probe six hours ago reappearing in a check I wrote tonight.
    SELF_GENERATED = {"MANIFEST.sha256", "DERIVATION-LOG.md"}
    extra = [r for r in sorted(on_disk) if r not in listed and r not in SELF_GENERATED]
    # ⛔ EXCLUDING BYTECODE FROM THE COMPARISON MADE THE LITTER INVISIBLE TO BOTH CHECKS. Caught the
    # same hour: filtering __pycache__ out of the digest AND out of the manifest comparison means 11
    # .pyc files sitting in the artifact are reported by nobody -- so the next person to notice is a
