    litter = sorted(str(f.relative_to(root)).replace(os.sep, "/") for f in root.rglob("*")
                    if f.is_file() and (any(x in CACHE_NAMES for x in f.parts)
                                        or f.suffix in CACHE_SUFFIXES))
    suffix = ""
