def lint(target_path):
    text = read_text(target_path)
    results = []
    for line_no, raw, status, fields in parse_rows(text):
        if status == "parse-error":
            results.append({
                "line": line_no, "verb": None, "classification": "PARSE-ERROR",
                "evidence": "row did not parse into 5 recognized columns: " + repr(fields),
                "pointer": None, "work_item": None, "raw": raw.strip(),
            })
            continue
        if fields["verb"] != "DONE":
            continue
        classification, evidence = classify_pointer(fields["pointer"], REPO)
        results.append({
            "line": line_no, "verb": "DONE", "classification": classification,
            "evidence": evidence, "pointer": fields["pointer"],
            "work_item": fields["work_item"], "raw": raw.strip(),
        })
    return results


def summarize(results):
    done_rows = [r for r in results if r["verb"] == "DONE"]
    parse_errors = [r for r in results if r["classification"] == "PARSE-ERROR"]
    by_class = {}
    for r in done_rows:
        by_class.setdefault(r["classification"], []).append(r)
    assertion_only = by_class.get("ASSERTION-ONLY", []) + by_class.get("SELF-REF-ONLY", [])
    return done_rows, parse_errors, by_class, assertion_only

def resolve_main(jsonl):
    """(target dict, reason) for one TOP-LEVEL session jsonl.

    The predicate is the exact complement of the one that excluded main all along: a session
    transcript is a `*.jsonl` sitting DIRECTLY in a project directory, not under `subagents/`.
    Stated as a complement on purpose — if the two predicates ever both reject a file, the file is
    visible in neither layer, which is the condition this script exists to end.
    """
    jsonl = Path(jsonl)
    if not jsonl.is_file():
        return None, f"not a file: {jsonl}"
    if jsonl.suffix != ".jsonl":
        return None, f"not a jsonl: {jsonl.name}"
    if jsonl.parent.name == "subagents":
        return None, "subagent transcript — agent_end_ingest.py owns this one"
    uuid = jsonl.stem
    if len(uuid) < 6:
        return None, f"session id too short to anchor: {uuid}"
    st = jsonl.stat()
    return {
        "jsonl": jsonl,
        "uuid": uuid,
        "uuid6": uuid[:6],
        "project": X.project_for_dir(jsonl.parent.name),
        "size": st.st_size,
        "mtime": int(st.st_mtime),
    }, ""


