def count_on_disk(root, srcdir, exclude, recursive=True):
    d = os.path.join(root, srcdir)
    if not os.path.isdir(d):
        return 0
    n = 0
    if recursive:
        for dirpath, _, files in os.walk(d):
            for fn in files:
                if fn.endswith(".md") and fn not in exclude:
                    n += 1
    else:
        for fn in os.listdir(d):
            if fn.endswith(".md") and fn not in exclude:
                n += 1
    return n


