def _tc_true_local(iso, datestr):
    """datetime in Jon's local wall time from the sidecar's UTC ISO stamp, or None."""
    import datetime as _dt
    try:
        base = _dt.datetime.strptime(iso[:19], "%Y-%m-%dT%H:%M:%S")
