def totals(recs: list[Rec]):
    t = {"input": 0, "output": 0, "cache_read": 0, "cache_creation": 0,
         "messages": len(recs), "cost_usd": 0.0}
    unpriced = set()
    for r in recs:
        t["input"] += r.inp
        t["output"] += r.out
        t["cache_read"] += r.cread
        t["cache_creation"] += r.cwrite
        c = r.cost()
        if c is None:
            unpriced.add(r.model)
