            n_asst += 1
            m = r.get("message") or {}
            u = m.get("usage")
            if not u:
                n_missing += 1
                continue
            mid = m.get("id") or r.get("uuid")
            if mid in seen_ids:
                continue  # streamed split of an already-counted message
            seen_ids.add(mid)
            model = m.get("model")
            add_usage(totals, model, u, unpriced_models)
            if turns is not None:
                if cur is None:  # assistant output before the first prompt
