        if len(active) > 1:
            findings.append({
                "cwd": cwd,
                "collision_type": "MULTIPLE_BACKGROUND_JOBS",
                "jobs": active
            })
        elif len(active) == 1:
            findings.append({
                "cwd": cwd,
                "collision_type": "SINGLE_ACTIVE_JOB",
                "jobs": active
            })
    return findings

