            if any(s in dirpath for s in SKIP_DIRS):
                continue
            n += sum(1 for f in filenames if f.endswith(EXEC_EXT))
        by_trunk[name] = n
        total += n
    return total, by_trunk, [getattr(e, "filename", str(e)) for e in unreadable]

