def filename_date(name):
    """Last ISO date in the filename, as a date, or None."""
    hits = DATE_RE.findall(name)
    if not hits:
        return None
    y, m, d = hits[-1]
    try:
        return datetime.date(int(y), int(m), int(d))
    except ValueError:
        return None


